Dataspatium.assets.register("presets/api/kartverket-adm.api.json","text","{\n  \"format\": \"dataspatium-api/1\",\n  \"id\": \"kartverket-adm\",\n  \"name\": \"Kartverket administrative enheter (WFS)\",\n  \"publisher\": \"Kartverket\",\n  \"description\": \"Fylken och kommuner i Norge från Kartverket (Geonorge) som geodata. Välj lager och hämta objekten med geometri.\",\n  \"docs\": \"https://kartkatalog.geonorge.no/metadata/administrative-enheter-kommuner/041f1e6e-bdbc-4091-b48f-8a5990f3cc5b\",\n  \"license\": {\n    \"name\": \"NLOD 2.0\",\n    \"url\": \"https://data.norge.no/nlod/no/2.0\"\n  },\n  \"level\": 1,\n  \"country\": \"NO\",\n  \"baseUrl\": \"https://wfs.geonorge.no/skwms1/wfs.administrative_enheter\",\n  \"auth\": {\n    \"type\": \"none\"\n  },\n  \"family\": {\n    \"type\": \"geodata\",\n    \"kind\": \"wfs\"\n  },\n  \"endpoints\": [],\n  \"notes\": \"Lagren hämtas från tjänsten när källan öppnas (GetCapabilities respektive tjänstekatalogen). Svaren är GeoJSON i WGS 84 och öppnas som kartor.\",\n  \"i18n\": {\n    \"en\": {\n      \"name\": \"Norwegian Mapping Authority administrative units (WFS)\",\n      \"description\": \"Counties and municipalities of Norway from Kartverket (Geonorge). Choose a layer and fetch the features with geometry.\",\n      \"notes\": \"The layers are read from the service when the source is opened (GetCapabilities or the service directory). Answers are GeoJSON in WGS 84 and open as maps.\"\n    },\n    \"da\": {\n      \"name\": \"Kartverket administrative enheder (WFS)\",\n      \"description\": \"Fylker og kommuner i Norge fra Kartverket (Geonorge) som geodata. Vælg et lag og hent objekterne med geometri.\",\n      \"notes\": \"Lagene hentes fra tjenesten, når kilden åbnes (GetCapabilities henholdsvis tjenestekataloget). Svarene er GeoJSON i WGS 84 og åbnes som kort.\"\n    },\n    \"nb\": {\n      \"name\": \"Kartverket administrative enheter (WFS)\",\n      \"description\": \"Fylker og kommuner i Norge fra Kartverket (Geonorge) som geodata. Velg lag og hent objektene med geometri.\",\n      \"notes\": \"Lagene hentes fra tjenesten når kilden åpnes (GetCapabilities respektive tjenestekatalogen). Svarene er GeoJSON i WGS 84 og åpnes som kart.\"\n    },\n    \"fi\": {\n      \"name\": \"Kartverket hallinnolliset yksiköt (WFS)\",\n      \"description\": \"Norjan fylket ja kunnat Kartverketiltä (Geonorge) paikkatietona. Valitse taso ja nouda kohteet geometrioineen.\",\n      \"notes\": \"Tasot noudetaan palvelusta, kun lähde avataan (GetCapabilities tai palveluhakemisto). Vastaukset ovat GeoJSONia WGS 84:ssä ja avautuvat karttoina.\"\n    },\n    \"is\": {\n      \"name\": \"Stjórnsýslueiningar Kartverket (WFS)\",\n      \"description\": \"Fylki og sveitarfélög í Noregi frá Kartverket (Geonorge) sem landupplýsingar. Veldu lag og sæktu fitjurnar með rúmfræði.\",\n      \"notes\": \"Lögin eru sótt úr þjónustunni þegar uppsprettan er opnuð (GetCapabilities eða þjónustuskráin). Svörin eru GeoJSON í WGS 84 og opnast sem kort.\"\n    }\n  }\n}\n");
